test('invoiceTotals no bulk discount for 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.discount, 0);
});

test('invoiceTotals applies bulk discount for exactly 10 units', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const expectedBulk = Math.round(10000 * 0.025);
  assert.equal(result.discount, expectedBulk);
});

test('invoiceTotals applies bulk discount for 11 units', () => {
  const invoice = {
    lines: [
      { qty: 11, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const expectedBulk = Math.round(11000 * 0.025);
  assert.equal(result.discount, expectedBulk);
});

test('invoiceTotals applies bulk discount for 20 units', () => {
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const expectedBulk = Math.round(20000 * 0.025);
  assert.equal(result.discount, expectedBulk);
});

test('invoiceTotals bulk discount after line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const lineTotal = 100000;
  const firstDiscount = Math.round(100000 * 0.1);
  const afterFirst = lineTotal - firstDiscount;
  const bulkDiscount = Math.round(afterFirst * 0.025);
  const totalExpected = firstDiscount + bulkDiscount;
  assert.equal(result.discount, totalExpected);
});

test('invoiceTotals bulk discount after tier discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 5, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const lineTotal = 100000;
  const firstDiscount = Math.round(100000 * 0.05);
  const afterFirst = lineTotal - firstDiscount;
  const bulkDiscount = Math.round(afterFirst * 0.025);
  const totalExpected = firstDiscount + bulkDiscount;
  assert.equal(result.discount, totalExpected);
});

test('invoiceTotals VAT calculated after bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  const lineTotal = 100000;
  const bulkDiscount = Math.round(lineTotal * 0.025);
  const afterDiscount = lineTotal - bulkDiscount;
  const expectedVat = Math.round(afterDiscount * 0.21);
  assert.equal(result.vat, expectedVat);
});

test('invoiceTotals bulk discount with line discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  const lineTotal = 100000;
  const firstDiscount = Math.round(lineTotal * 0.1);
  const afterFirst = lineTotal - firstDiscount;
  const bulkDiscount = Math.round(afterFirst * 0.025);
  const totalDiscount = firstDiscount + bulkDiscount;
  const afterAllDiscounts = lineTotal - totalDiscount;
  const expectedVat = Math.round(afterAllDiscounts * 0.21);

  assert.equal(result.discount, totalDiscount);
  assert.equal(result.vat, expectedVat);
  assert.equal(result.total, lineTotal - totalDiscount + expectedVat);
});

test('invoiceTotals mixed quantities: some with bulk, some without', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const line1Discount = 0;
  const line2Discount = Math.round(10000 * 0.025);
  const totalExpected = line1Discount + line2Discount;
  assert.equal(result.discount, totalExpected);
});

test('invoiceTotals multiple lines all with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      { qty: 15, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const line1Discount = Math.round(10000 * 0.025);
  const line2Discount = Math.round(15000 * 0.025);
  const totalExpected = line1Discount + line2Discount;
  assert.equal(result.discount, totalExpected);
});

test('invoiceTotals bulk discount with zero line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const expectedDiscount = Math.round(50000 * 0.025);
  assert.equal(result.discount, expectedDiscount);
  assert.equal(result.total, 50000 - expectedDiscount);
});

test('invoiceTotals bulk discount with 100% line discount blocked', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 100, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.discount, 100000);
  assert.equal(result.total, 0);
});

test('invoiceTotals bulk discount is additional to line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 5, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const expected = Math.round(100000 * 0.05) + Math.round((100000 - Math.round(100000 * 0.05)) * 0.025);
  assert.equal(result.discount, expected);
  assert.ok(result.discount > Math.round(100000 * 0.05));
});

test('invoiceTotals large quantity bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 1000, unitPrice: 100, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const expectedDiscount = Math.round(100000 * 0.025);
  assert.equal(result.discount, expectedDiscount);
});

test('invoiceTotals bulk discount rounding', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 333, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(Number.isInteger(result.discount), true);
  assert.ok(result.discount > 0);
});

test('invoiceTotals bulk discount with voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 0 },
    ],
    voucher: { code: 'SAVE', amount: 1000 },
  };
  const result = invoiceTotals(invoice);
  const expectedDiscount = Math.round(100000 * 0.025);
  assert.equal(result.discount, expectedDiscount);
  assert.equal(result.voucher, 1000);
});

test('invoiceTotals bulk discount 2.5% calculation precision', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1234, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const expectedDiscount = Math.round(12340 * 0.025);
  assert.equal(result.discount, expectedDiscount);
});

test('invoiceTotals formula with bulk discount: total = subtotal - discount + vat', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.total, result.subtotal - result.discount + result.vat);
});

test('invoiceTotals bulk discount does not apply below 10 units', () => {
  for (let qty = 1; qty < 10; qty++) {
    const invoice = {
      lines: [
        { qty, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      ],
    };
    const result = invoiceTotals(invoice);
    assert.equal(result.discount, 0, `qty ${qty} should have no discount`);
  }
});

test('invoiceTotals bulk discount applies at 10 units and above', () => {
  for (let qty = 10; qty <= 20; qty++) {
    const invoice = {
      lines: [
        { qty, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      ],
    };
    const result = invoiceTotals(invoice);
    const expected = Math.round(qty * 1000 * 0.025);
    assert.equal(result.discount, expected, `qty ${qty} should have bulk discount`);
  }
});

